import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (event) => {
    event.preventDefault();
    setLoading(true);
    setError('');

    try {
      await register(form.name, form.email, form.password);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Unable to create account.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-shell auth-shell--register">
      <section className="auth-panel auth-panel--wide">
        <div className="auth-card">
          <div className="auth-card__header">
            <span className="eyebrow">Create account</span>
            <h2>Join the DRMS workspace</h2>
            <p>The first registered account becomes the bootstrap admin. Later accounts start as Authorized User.</p>
          </div>

          {error && <div className="message message--error">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="grid grid--2">
              <div className="field">
                <label>Full name</label>
                <input
                  className="input"
                  value={form.name}
                  onChange={(event) => setForm({ ...form, name: event.target.value })}
                  placeholder="Your full name"
                  required
                />
              </div>

              <div className="field">
                <label>Email address</label>
                <input
                  className="input"
                  type="email"
                  value={form.email}
                  onChange={(event) => setForm({ ...form, email: event.target.value })}
                  placeholder="you@example.com"
                  required
                />
              </div>
            </div>

            <div className="field">
              <label>Password</label>
              <div className="password-row">
                <input
                  className="input"
                  type={showPassword ? 'text' : 'password'}
                  value={form.password}
                  onChange={(event) => setForm({ ...form, password: event.target.value })}
                  placeholder="Create a strong password"
                  required
                />
                <button type="button" className="button button--ghost" onClick={() => setShowPassword((value) => !value)}>
                  {showPassword ? 'Hide' : 'Show'}
                </button>
              </div>
            </div>

            <button type="submit" className="button button--primary button--full" disabled={loading}>
              {loading ? 'Creating account...' : 'Create account'}
            </button>
          </form>

          <p className="auth-footer">Already have an account? <Link to="/login">Sign in</Link></p>

          <div className="info-card">
            <h3>Role administration</h3>
            <p>Admins can later promote accounts to Record Manager or Auditor from the dedicated Users page.</p>
          </div>
        </div>
      </section>
    </div>
  );
}
